import { ReactNode, useEffect, useState } from 'react';

import { c } from 'ttag';

import { Button } from '@proton/atoms';
import { createToken, getTokenStatus } from '@proton/shared/lib/api/payments';
import { MIN_BITCOIN_AMOUNT } from '@proton/shared/lib/constants';
import { Currency } from '@proton/shared/lib/interfaces';
import { PAYMENT_TOKEN_STATUS } from '@proton/components/payments/core';

import { Alert, Bordered, Loader, Price } from '../../components';
import { useApi } from '../../hooks';
import BitcoinDetails from './BitcoinDetails';
import BitcoinQRCode from './BitcoinQRCode';
import BitcoinInfoMessage from './BitcoinInfoMessage';

interface Props {
    amount: number;
    currency: Currency;
    type: string;
    awaitingPayment?: boolean;
    enableValidation?: boolean;
    onTokenValidated?: () => void;
}

interface TokenResult {
    Token: string;
    Data: { CoinAddress: string; CoinAmount: string | number };
}

const Bitcoin = ({ amount, currency, type, awaitingPayment = false, enableValidation = false, onTokenValidated }: Props) => {
    const api = useApi();
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(false);
    const [model, setModel] = useState<{ token?: string; amountBitcoin: string | number; address: string }>({ amountBitcoin: '', address: '' });
    const [validated, setValidated] = useState(false);

    const request = async () => {
        setLoading(true);
        setError(false);
        try {
            const result = await api<TokenResult>(createToken({
                Amount: amount,
                Currency: currency,
                Payment: { Type: 'cryptocurrency', Details: { Coin: 'bitcoin' } },
            }));
            setModel({ token: result.Token, address: result.Data.CoinAddress, amountBitcoin: result.Data.CoinAmount });
        } catch {
            setError(true);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (amount >= MIN_BITCOIN_AMOUNT) void request();
    }, [amount, currency]);

    useEffect(() => {
        if (!enableValidation || !model.token || validated) return;
        let active = true;
        let timeout: ReturnType<typeof setTimeout>;
        const poll = async () => {
            try {
                const result = await api<{ Status: PAYMENT_TOKEN_STATUS }>(getTokenStatus(model.token!));
                if (!active) return;
                if (result.Status === PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE) {
                    setValidated(true);
                    onTokenValidated?.();
                    return;
                }
            } catch {
                // Keep checking while the payment remains unresolved.
            }
            if (active) timeout = setTimeout(poll, 10000);
        };
        timeout = setTimeout(poll, 10000);
        return () => { active = false; clearTimeout(timeout); };
    }, [api, enableValidation, model.token, validated, onTokenValidated]);

    if (amount < MIN_BITCOIN_AMOUNT) {
        const i18n = (value: ReactNode) => c('Info').jt`Amount below minimum (${value}).`;
        return <Alert className="mb-4" type="warning">{i18n(<Price key="price" currency={currency}>{MIN_BITCOIN_AMOUNT}</Price>)}</Alert>;
    }
    if (loading) return <div data-testid="circle-loader"><Loader /></div>;
    if (error || !model.address) return <><Alert className="mb-4" type="error">{c('Error').t`Error connecting to the Bitcoin API.`}</Alert><Button onClick={() => void request()}>{c('Action').t`Try again`}</Button></>;

    return <Bordered className="bg-weak rounded">
        <div className="p-4 border-bottom"><BitcoinQRCode className="flex flex-align-items-center flex-column" amount={Number(model.amountBitcoin)} address={model.address} /></div>
        <BitcoinDetails amount={Number(model.amountBitcoin)} address={model.address} />
        <div className="pt-4 px-4"><BitcoinInfoMessage type={type} awaitingPayment={awaitingPayment} /></div>
    </Bordered>;
};

export default Bitcoin;
